INSERT INTO changelog (title, body, created_at) VALUES ('Порядок: прохання клієнтів → правки, менше зайвого', 'Прохання клієнтів з переписки (по їхній CRM чи сайту) більше не падають тобі в задачі — вони стають правками R-N у потрібному проєкті (сайт → «Сайт», решта → CRM клієнта). Для вже створених: Клієнт → Задачі → «Перенести в правки». У Telegram «Підтверди» пише, в який проєкт піде правка. Рев’ю тижня прибрано з меню, Центру і ранкового зведення. «Файли» і старі «Матеріали» сховані з картки клієнта (матеріали тепер у «Контенті»; повернути — «+ Розділ»). Контент → Матеріали: документи з прев’ю або іконкою типу (PDF, Excel, Numbers, Word). Meta: «Звіт клієнту» — кнопка вгорі замість блоку, діагностика коротка (назва кроку кольором і 3 дії, деталі — в «чому і як»).', datetime('now'));
